L000093		\title{A digitally controlled silicon quantum processing unit}
L000094		\author{Members of the HRL Quantum Team and Collaborators}
L000095	
L000096		\newcommand{\emailstatement}{Jacob Z. Blumoff (jzblumoff@hrl.com), Thaddeus D. Ladd (tdladd@hrl.com), Matthew D. Reed (mdreed@hrl.com)}
L000097		\ifarxiv
L000098		\thanks{Corresponding authors: \emailstatement}
L000099		\else
L000100	
